// TTL cache and bounded JSON fetcher for OAuth metadata discovery (R2/R3).
//
// Discovery probes several well-known URLs per connection and most of them are
// expected to 404. Without caching, every recovery attempt re-runs the whole
// permutation list against the same origins, so negative results are cached too
// — a probe storm against an authorization server is indistinguishable from an
// attack and will get the deployment rate-limited.
//
// Every response here is remote-controlled, so the fetcher is bounded in size
// and never throws: callers get a discriminated result, not an exception.

/** Bytes of metadata body we are willing to buffer before giving up. */
const MAX_METADATA_BYTES = 256 * 1024;

const DEFAULT_TTL_MS = 10 * 60 * 1000;
const DEFAULT_NEGATIVE_TTL_MS = 60 * 1000;
const MAX_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_ENTRIES = 128;

export type MetadataFetchOutcome<T> =
  | { readonly ok: true; readonly value: T; readonly url: string }
  | {
      readonly ok: false;
      readonly url: string;
      /**
       * `not_found` is the expected outcome for a probe that should fall through
       * to the next candidate. Everything else stops the permutation walk.
       */
      readonly reason:
        | "not_found"
        | "http_error"
        | "network_error"
        | "invalid_json"
        | "too_large"
        | "invalid_shape";
      readonly status?: number;
    };

export interface MetadataFetchOptions {
  readonly fetchImpl?: typeof fetch;
  readonly signal?: AbortSignal;
  readonly timeoutMs?: number;
  readonly cache?: MetadataCache;
}

interface CacheEntry {
  readonly outcome: MetadataFetchOutcome<unknown>;
  readonly expiresAt: number;
}

export interface MetadataCacheOptions {
  readonly ttlMs?: number;
  readonly negativeTtlMs?: number;
  readonly now?: () => number;
}

/**
 * Insertion-ordered TTL cache. Bounded so a hostile or misconfigured server
 * cannot grow it without limit by advertising an unbounded set of issuers.
 */
export class MetadataCache {
  private readonly entries = new Map<string, CacheEntry>();
  private readonly ttlMs: number;
  private readonly negativeTtlMs: number;
  private readonly now: () => number;

  constructor(options: MetadataCacheOptions = {}) {
    this.ttlMs = clampTtl(options.ttlMs, DEFAULT_TTL_MS);
    this.negativeTtlMs = clampTtl(
      options.negativeTtlMs,
      DEFAULT_NEGATIVE_TTL_MS,
    );
    this.now = options.now ?? (() => Date.now());
  }

  get<T>(key: string): MetadataFetchOutcome<T> | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= this.now()) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.outcome as MetadataFetchOutcome<T>;
  }

  set(
    key: string,
    outcome: MetadataFetchOutcome<unknown>,
    ttlOverrideMs?: number,
  ): void {
    const baseTtl = outcome.ok ? this.ttlMs : this.negativeTtlMs;
    const ttl =
      typeof ttlOverrideMs === "number" && Number.isFinite(ttlOverrideMs)
        ? clampTtl(ttlOverrideMs, baseTtl)
        : baseTtl;

    // Re-inserting moves the key to the end so eviction stays insertion-ordered.
    this.entries.delete(key);
    this.entries.set(key, { outcome, expiresAt: this.now() + ttl });

    while (this.entries.size > MAX_ENTRIES) {
      const oldest = this.entries.keys().next();
      if (oldest.done) break;
      this.entries.delete(oldest.value);
    }
  }

  clear(): void {
    this.entries.clear();
  }

  get size(): number {
    return this.entries.size;
  }
}

/**
 * Fetch a JSON metadata document with bounds, TTL caching, and negative caching.
 * Never throws except for caller-initiated aborts, which propagate so the
 * orchestrator can distinguish cancellation from a discovery failure.
 */
export async function fetchMetadataJson<T = unknown>(
  url: string,
  options: MetadataFetchOptions = {},
): Promise<MetadataFetchOutcome<T>> {
  const cache = options.cache;
  const cached = cache?.get<T>(url);
  if (cached) return cached;

  const { outcome, ttlMs } = await fetchMetadataJsonUncached<T>(url, options);

  // An abort is a property of this call, not of the URL — caching it would
  // poison later attempts that were never cancelled.
  const aborted =
    outcome.ok === false &&
    outcome.reason === "network_error" &&
    options.signal?.aborted === true;
  if (!aborted) cache?.set(url, outcome, ttlMs);
  return outcome;
}

interface UncachedFetch<T> {
  readonly outcome: MetadataFetchOutcome<T>;
  /** TTL override derived from `Cache-Control`, when the server sent one. */
  readonly ttlMs?: number;
}

async function fetchMetadataJsonUncached<T>(
  url: string,
  options: MetadataFetchOptions,
): Promise<UncachedFetch<T>> {
  const fetchImpl = options.fetchImpl ?? globalThis.fetch;
  if (typeof fetchImpl !== "function") {
    return { outcome: { ok: false, url, reason: "network_error" } };
  }

  const controller = new AbortController();
  const abortOuter = (): void => controller.abort();
  options.signal?.addEventListener("abort", abortOuter, { once: true });
  const timeoutMs = options.timeoutMs;
  const timer =
    typeof timeoutMs === "number" && timeoutMs > 0
      ? setTimeout(() => controller.abort(), timeoutMs)
      : undefined;

  try {
    let response: Response;
    try {
      response = await fetchImpl(url, {
        method: "GET",
        // Discovery documents are public and MUST NOT carry ambient credentials
        // or a bearer token; sending one would leak it to an unverified origin.
        headers: { Accept: "application/json" },
        credentials: "omit",
        redirect: "follow",
        signal: controller.signal,
      });
    } catch {
      return { outcome: { ok: false, url, reason: "network_error" } };
    }

    const ttlMs = ttlFromCacheControl(
      typeof response.headers?.get === "function"
        ? response.headers.get("cache-control")
        : null,
    );
    const status = response.status;

    if (status === 404 || status === 410) {
      return {
        outcome: { ok: false, url, reason: "not_found", status },
        ttlMs,
      };
    }
    if (!response.ok) {
      return {
        outcome: { ok: false, url, reason: "http_error", status },
        ttlMs,
      };
    }

    let text: string;
    try {
      text = await response.text();
    } catch {
      return { outcome: { ok: false, url, reason: "network_error", status } };
    }
    if (text.length > MAX_METADATA_BYTES) {
      return {
        outcome: { ok: false, url, reason: "too_large", status },
        ttlMs,
      };
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      return {
        outcome: { ok: false, url, reason: "invalid_json", status },
        ttlMs,
      };
    }
    if (!isPlainObject(parsed)) {
      return {
        outcome: { ok: false, url, reason: "invalid_shape", status },
        ttlMs,
      };
    }

    return { outcome: { ok: true, url, value: parsed as T }, ttlMs };
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    options.signal?.removeEventListener("abort", abortOuter);
  }
}

/** Read `Cache-Control: max-age=<n>` as a TTL override, in milliseconds. */
export function ttlFromCacheControl(header: string | null): number | undefined {
  if (!header) return undefined;
  if (/(^|[\s,])no-store([\s,]|$)/i.test(header)) return 0;
  const match = /(?:^|[\s,])max-age\s*=\s*"?(\d+)"?/i.exec(header);
  if (!match) return undefined;
  const seconds = Number.parseInt(match[1], 10);
  if (!Number.isFinite(seconds) || seconds < 0) return undefined;
  return Math.min(seconds * 1000, MAX_TTL_MS);
}

export function isPlainObject(
  value: unknown,
): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function clampTtl(value: number | undefined, fallback: number): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    return fallback;
  }
  return Math.min(value, MAX_TTL_MS);
}
